import{b as o,O as r,g as n,j as s}from"./chunks/framework.DSt9LnBW.js";const q=JSON.parse('{"title":"项目制与产品制：同一套流程，两种跑法","description":"软件开发生命周期可以分为六步：需求、设计、编码、测试、上线、运维，一圈一圈地跑。但有个前提：这六步是在什么制度下跑的。同一套流程，放在项目制里和放在产品制里，每一步的目标、节奏、判定标准、谁说了算，全都不一样。这个差异不是\\"风格不同\\"，它会一路下沉到你的每一行代码、每一个测试用例。","frontmatter":{"date":"2026-09-27T00:00:00.000Z","tags":["互联网","软件工程","产品","流程"],"sidebar":false,"pageClass":"blog-post","prev":false,"next":false,"lastUpdated":false},"headers":[],"relativePath":"blog/internet-years/project-vs-product/index.md","filePath":"个人博客/在互联网的那些年/3.项目制与产品制.md","lastUpdated":1790504615000}'),a={name:"blog/internet-years/project-vs-product/index.md"};function l(d,t,u,p,e,g){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="项目制与产品制-同一套流程-两种跑法" tabindex="-1">项目制与产品制：同一套流程，两种跑法 <a class="header-anchor" href="#项目制与产品制-同一套流程-两种跑法" aria-label="Permalink to &quot;项目制与产品制：同一套流程，两种跑法&quot;">​</a></h1><p>软件开发生命周期可以分为六步：需求、设计、编码、测试、上线、运维，一圈一圈地跑。</p><p>但有个前提：<strong>这六步是在什么制度下跑的。</strong></p><p>同一套流程，放在项目制里和放在产品制里，每一步的目标、节奏、判定标准、谁说了算，全都不一样。这个差异不是&quot;风格不同&quot;，它会一路下沉到你的每一行代码、每一个测试用例。</p><p>先把两个词说清楚，它们在日常对话里太容易被混着用：</p><table tabindex="0"><thead><tr><th></th><th>项目制</th><th>产品制</th></tr></thead><tbody><tr><td>组织单位</td><td>一个个项目</td><td>一个长期产品</td></tr><tr><td>边界</td><td>有明确的开始和结束</td><td>没有结束</td></tr><tr><td>团队</td><td>随项目聚散</td><td>相对稳定</td></tr><tr><td>交给谁</td><td>甲方 / 客户</td><td>用户</td></tr></tbody></table><p>一句大白话概括：</p><blockquote><p><strong>项目制卖的是&quot;确定的交付&quot;，产品制卖的是&quot;持续的价值&quot;。</strong></p></blockquote><p>前者收钱的时间点是&quot;验收通过&quot;，后者收钱的时间点是&quot;用户愿意留下来&quot;。</p><p><strong>这个收钱时间点的差异，是后面所有差异的根。</strong> 下面顺着那六步，一步步看它怎么变形。</p><p><img src="https://op.yychuiyan.com/docs-blog/project-vs-product-flow.png" alt="六步流程在两种制度下的对照：上排项目制每步对应范围冻结、一次到位、交付物、验收、里程碑、质保，末端走向交付签字终止；下排产品制每步对应持续发现、演进式、资产、质量信息、起点、运营，末端回到第一步形成循环"></p><h2 id="一、需求-范围冻结-还是持续发现" tabindex="-1">一、需求：范围冻结，还是持续发现 <a class="header-anchor" href="#一、需求-范围冻结-还是持续发现" aria-label="Permalink to &quot;一、需求：范围冻结，还是持续发现&quot;">​</a></h2><p><strong>项目制</strong>里，需求是被合同冻结的。</p><p>不是不能改，是&quot;改要重新计价、重新排期&quot;。这常常被吐槽成官僚，但它其实是一种保护：乙方按一个确定的范围报价，范围一变，成本和风险就全压在他身上。<strong>冻结范围，是这门生意能成立的前提。</strong></p><p>所以项目制的需求文档写得很重——它是验收依据，是要签字的东西。</p><p><strong>产品制</strong>里，需求没有&quot;冻结&quot;这回事。</p><p>判断一条需求的标准不是&quot;合同里有没有&quot;，而是&quot;用户需不需要、数据支持不支持&quot;。需求会随着对问题的理解加深不断被推翻——今天以为要做 A，一个月后发现真正的问题在 B。</p><p><strong>同一个动作：改需求。</strong></p><ul><li>项目制里是<strong>生意</strong>：走变更流程、重新报价、重新排期</li><li>产品制里是<strong>常态</strong>：进下一轮迭代，改就改了</li></ul><p>两种制度各有各的翻车方式：</p><ul><li>项目制的需求一旦冻结，就失去了纠错机会。等到交付那天，用户的需求早变了，但合同不允许你变——<strong>交付了一个正确的、但已经没人要的东西</strong></li><li>产品制的需求如果没有纪律，会无限蔓延。什么都做一点，什么都不做完，最后变成一个谁都不认识的四不像</li></ul><h2 id="二、设计-一次到位-还是演进式" tabindex="-1">二、设计：一次到位，还是演进式 <a class="header-anchor" href="#二、设计-一次到位-还是演进式" aria-label="Permalink to &quot;二、设计：一次到位，还是演进式&quot;">​</a></h2><p><strong>项目制</strong>的设计是一次性的，而且要评审签字。</p><p>因为改设计的代价太高——设计一改，前面写好的代码要返工，后面排好的计划要重排。所以要在动工前把方案定死。这也是为什么项目制特别依赖&quot;需求稳定&quot;这个前提。</p><p><strong>产品制</strong>的设计是演进的。</p><p>允许&quot;先这么做，下个版本再改&quot;。因为这个版本本来就不是最后一次，方案的寿命比代码短，没必要为它开一场三天的评审会。</p><p><strong>同一个动作：重构。</strong></p><ul><li>项目制里，重构<strong>没有预算</strong>——合同里根本没有这一项，做了就是白干，做完甲方也不会多付钱</li><li>产品制里，重构是<strong>必须还的债</strong>——代码要养很多年，不还债，下一轮迭代就慢一步</li></ul><p>一句话：<strong>项目制为&quot;改不动&quot;负责，产品制为&quot;改得快&quot;负责。</strong></p><h2 id="三、编码-交付物-还是资产" tabindex="-1">三、编码：交付物，还是资产 <a class="header-anchor" href="#三、编码-交付物-还是资产" aria-label="Permalink to &quot;三、编码：交付物，还是资产&quot;">​</a></h2><p><strong>项目制</strong>里，代码是<strong>交付物</strong>。</p><p>写完、验收通过，责任就转移了。所以可维护性、可读性的优先级天然低——反正后面的维护不归我。这不是工程师不专业，是制度在引导：<strong>你把可维护性做到极致，验收标准里也没有这一项。</strong></p><p><strong>产品制</strong>里，代码是<strong>资产</strong>。</p><p>要养很多年，每一轮迭代都要在同一份代码上动刀。所以可测试性、可读性、依赖管理的优先级都被顶上去——不是为了好看，是为了半年后还能改。</p><p><strong>同一个动作：写文档。</strong></p><ul><li>项目制里，文档是<strong>交付物</strong>：要验收，写够、写全</li><li>产品制里，文档是<strong>负债</strong>：几个月就过期，写多了维护不过来</li></ul><p>所以产品制的团队更依赖&quot;代码自解释 + 自动化测试&quot;来承载知识，而不是靠文档。这个选择看着随意，其实是制度推出来的。</p><h2 id="四、测试-验收-还是质量信息" tabindex="-1">四、测试：验收，还是质量信息 <a class="header-anchor" href="#四、测试-验收-还是质量信息" aria-label="Permalink to &quot;四、测试：验收，还是质量信息&quot;">​</a></h2><p>这一节值得单独展开，因为它是两种制度差异最明显的地方。</p><p>上一篇说过一句话：<strong>测试不生产 bug，测试生产&quot;质量信息&quot;。</strong> 这句话在两种制度里的落地方式完全不同。</p><p><strong>项目制</strong>里，测试的目标是<strong>验收</strong>。</p><p>证明&quot;合同约定的事情做完了&quot;。测试用例从需求文档来，需求写完、用例写完、执行通过、签字验收，任务就结束了。测试的终点是一份验收报告。</p><p><strong>产品制</strong>里，测试的目标是<strong>生产质量信息</strong>。</p><p>回答的是&quot;这个版本能不能上、风险在哪、上了之后有没有变差&quot;。测试的终点不是一个通过率，而是<strong>上线之后的指标</strong>。</p><p>同一个&quot;测试&quot;，两边问的问题不一样：</p><table tabindex="0"><thead><tr><th></th><th>项目制</th><th>产品制</th></tr></thead><tbody><tr><td>测试依据</td><td>需求文档 / 合同范围</td><td>用户真实使用路径</td></tr><tr><td>通过标准</td><td>验收通过</td><td>指标没变差</td></tr><tr><td>什么时候结束</td><td>验收签字那天</td><td>永不结束，持续回归</td></tr><tr><td>出了问题</td><td>找乙方修（质保期内）</td><td>自己修，还要复盘</td></tr></tbody></table><p>差别最大的是最后一行。<strong>项目制里，测试的终点是&quot;交付&quot;；产品制里，测试的终点是&quot;下一个版本&quot;。</strong></p><h2 id="五、上线-里程碑-还是起点" tabindex="-1">五、上线：里程碑，还是起点 <a class="header-anchor" href="#五、上线-里程碑-还是起点" aria-label="Permalink to &quot;五、上线：里程碑，还是起点&quot;">​</a></h2><p><strong>项目制</strong>里，上线是一个<strong>交付里程碑</strong>。</p><p>系统移交、验收签字、项目结束。之后进入质保期。上线这个动作本身，在项目制里是&quot;结束&quot;的代名词。</p><p><strong>产品制</strong>里，上线是<strong>起点</strong>。</p><p>上一篇那句&quot;上线不是终点，而是第一个真正的起点&quot;说的就是这里。灰度发布、观察数据、收集反馈，然后进下一轮。上线那天不是松了口气，是刚开始紧张。</p><p>同一个词&quot;上线&quot;，一边是句号，一边是逗号。</p><h2 id="六、运维-质保-还是运营" tabindex="-1">六、运维：质保，还是运营 <a class="header-anchor" href="#六、运维-质保-还是运营" aria-label="Permalink to &quot;六、运维：质保，还是运营&quot;">​</a></h2><p><strong>项目制</strong>里，运维 = <strong>质保期内的缺陷修复</strong>。</p><p>合同里写好质保三个月还是一年。这期间出的 bug 我修，质保一过，责任结束。至于这个系统好不好用、要不要优化，不在合同范围内。</p><p><strong>产品制</strong>里，运维 = <strong>持续运营</strong>。</p><p>监控、响应、迭代，都是日常工作。没有&quot;质保期&quot;这个概念，因为责任根本没有终点——<strong>用户还在用，你就还在负责。</strong></p><h2 id="七、同一动作-两种含义-根因在哪" tabindex="-1">七、同一动作，两种含义：根因在哪 <a class="header-anchor" href="#七、同一动作-两种含义-根因在哪" aria-label="Permalink to &quot;七、同一动作，两种含义：根因在哪&quot;">​</a></h2><p>把前面六节放在一起，你会发现同一个结构在反复出现：</p><table tabindex="0"><thead><tr><th>动作</th><th>项目制</th><th>产品制</th></tr></thead><tbody><tr><td>改需求</td><td>生意：走流程、重新计价</td><td>常态：进下一轮迭代</td></tr><tr><td>重构</td><td>没有预算，白干</td><td>必须还的债</td></tr><tr><td>写详细文档</td><td>交付物，写够写全</td><td>负债，过期比写得快</td></tr><tr><td>做自动化 / 压测</td><td>一次性成本，交付后闲置</td><td>长期资产，每轮都回本</td></tr><tr><td>赶进度加班</td><td>换交付节点</td><td>换一个迭代，但不值得</td></tr><tr><td>追数据</td><td>基本不需要</td><td>唯一有效的说话方式</td></tr></tbody></table><p>同一件事，在两边含义相反。根因还是那一句：</p><blockquote><p><strong>项目制为&quot;做完&quot;收费，产品制为&quot;有用&quot;收费。</strong></p></blockquote><p>&quot;做完&quot;可以用签字确认，&quot;有用&quot;只能用指标证明。制度不同，评价体系就不同，落到每个人头上的动作标准自然也不同。</p><p>所以从项目制跳到产品制的人，最容易不适应的不是技术，是<strong>没人给你一个确定的需求了</strong>。以前需求是别人给你的、写在文档里的；现在需求要你自己去找、去猜、去用数据验证。</p><h2 id="八、如果只有项目经理" tabindex="-1">八、如果只有项目经理 <a class="header-anchor" href="#八、如果只有项目经理" aria-label="Permalink to &quot;八、如果只有项目经理&quot;">​</a></h2><p>聊到制度，绕不开一个日常里被叫混的问题：<strong>项目经理和产品经理，到底是不是一个角色？</strong></p><p>不是。一句话区分：</p><table tabindex="0"><thead><tr><th></th><th>项目经理</th><th>产品经理</th></tr></thead><tbody><tr><td>管什么</td><td><strong>怎么按时做完</strong></td><td><strong>做的是不是对的东西</strong></td></tr><tr><td>对谁负责</td><td>交付节点、范围、预算</td><td>用户价值、业务指标</td></tr><tr><td>核心动作</td><td>计划、协调、推进、盯风险</td><td>判断、取舍、验证</td></tr><tr><td>怕什么</td><td>延期、超预算、范围蔓延</td><td>做了没人用、方向错了</td></tr></tbody></table><p>那如果团队里<strong>只有项目经理</strong>、没有产品经理，会怎样？</p><p>先说结论：<strong>这不是一个优缺点问题，而是一个&quot;需求从哪来&quot;的问题。</strong></p><h3 id="在项目制里-只有项目经理是正常的" tabindex="-1">在项目制里，只有项目经理是正常的 <a class="header-anchor" href="#在项目制里-只有项目经理是正常的" aria-label="Permalink to &quot;在项目制里，只有项目经理是正常的&quot;">​</a></h3><p>因为需求由甲方提供——甲方事实上就站在产品经理那个位置上。项目经理接力的是&quot;给定范围&quot;，负责把它变成&quot;按时交付&quot;。这是一套完整的分工，不是缺了一角。</p><p>这时它的优势很实在：</p><ul><li><strong>交付确定性最强</strong>：计划、协调、推进、盯风险，正是项目经理的主场</li><li><strong>决策链短</strong>：&quot;做什么&quot;由合同定，&quot;怎么做&quot;一个人拍板，不拉扯</li><li><strong>成本最低</strong>：少一个角色。这也是很多小团队这么干的现实原因</li></ul><h3 id="到了产品制-同一个配置就变成了缺位" tabindex="-1">到了产品制，同一个配置就变成了缺位 <a class="header-anchor" href="#到了产品制-同一个配置就变成了缺位" aria-label="Permalink to &quot;到了产品制，同一个配置就变成了缺位&quot;">​</a></h3><p>因为产品制里没人给你需求——需求要自己找。这时候只有项目经理，会出现三个具体的问题：</p><ol><li><strong>需求变成传声筒</strong>：没人负责判断&quot;什么值得做&quot;，只能谁嗓门大听谁的</li><li><strong>只对&quot;做完&quot;负责，不对&quot;有用&quot;负责</strong>：项目经理的天然目标是按期交付，上线即完成；至于上线之后有没有人用、指标有没有变好，没有人的 KPI 落在那</li><li><strong>需求真空</strong>：没人定方向，但活总得有人干——于是开发自己猜、老板随手拍、客户临时加。<strong>看着每个人都很忙，但没人对方向负责</strong></li></ol><p>所以判断很简单：</p><ul><li>需求从合同 / 甲方来 → 项目经理够用，甚至更高效</li><li>需求要自己去找 → 必须有产品经理，否则整个团队缺一个&quot;判断方向、用数据说话&quot;的人</li></ul><p>这也是很多团队从项目制转产品制时最容易踩的坑：<strong>组织形态换了，角色却没补。</strong> 计划排得很漂亮，交付节奏也很稳——只是没人能回答&quot;我们为什么做这个&quot;。</p><p>写到这里，可以把第七节那句根因再收一层：</p><blockquote><p>项目制为&quot;做完&quot;收费，产品制为&quot;有用&quot;收费。<strong>项目经理天然对前者负责，产品经理才对后者负责。</strong> 少哪个角色，取决于你在收哪种钱。</p></blockquote><h2 id="九、中间态-项目养产品" tabindex="-1">九、中间态：项目养产品 <a class="header-anchor" href="#九、中间态-项目养产品" aria-label="Permalink to &quot;九、中间态：项目养产品&quot;">​</a></h2><p>现实里，纯粹的一种很少。大部分公司的真实状态是<strong>混合</strong>。</p><p>一条常见的路径是：<strong>用项目制起家，再把能力沉淀成产品。</strong></p><p>项目交付带来现金流（先活下来），同时在项目里积累对某个领域的理解；等到同一类需求反复出现，就把它抽成一个产品，从&quot;按项目收费&quot;转向&quot;按产品收费&quot;。</p><p>判断有没有真在&quot;养&quot;，只看一个问题：</p><blockquote><p><strong>这个项目做完了，有东西沉淀下来吗？</strong></p></blockquote><ul><li>同一类需求已经做了三次 → 该抽成产品了</li><li>沉淀下来的是可复用的能力、组件、领域知识 → 养成了</li><li>沉淀下来的是一堆只有这个客户能用的定制代码 → 没养成，只是又做了一个项目</li></ul><p><img src="https://op.yychuiyan.com/docs-blog/project-to-product.png" alt="项目养产品的演进路径：项目交付提供现金流并积累领域理解，同一类需求重复三次后抽象沉淀为可复用能力，进而转为产品持续迭代；旁注两条翻车路径——永远抽不出产品、过早产品化"></p><p>两种翻车方式也要说清楚：</p><ul><li><strong>永远抽不出产品</strong>：被&quot;来一个做一个&quot;的节奏绑住，现金流很稳但天花板很低。</li><li><strong>过早产品化</strong>：拿项目的钱去养一个还没人验证的产品，两边都做不好。这其实就是<a href="/blog/internet-years/product-lifecycle/">产品生命周期</a>那张表里说的&quot;导入期过早优化&quot;——只是换了个层面。</li></ul><h2 id="十、那么-该选哪一种" tabindex="-1">十、那么，该选哪一种 <a class="header-anchor" href="#十、那么-该选哪一种" aria-label="Permalink to &quot;十、那么，该选哪一种&quot;">​</a></h2><p>没有普适答案，判断标准还是那个：<strong>你卖的是确定性，还是价值。</strong></p><ul><li>需求明确、一次性交付、按合同验收（外包、系统集成、定制实施）→ <strong>项目制更合理</strong>，它的边界感就是优势</li><li>需求不确定、要持续迭代、靠用户留存活（互联网产品、SaaS）→ <strong>产品制更合理</strong>，它的反馈速度就是优势</li></ul><p>选错了会怎样？用项目制做互联网产品，会得到一个&quot;交付完就没人管&quot;的东西；用产品制接定制项目，会在一个明确范围的事情上无休止地投入。</p><h2 id="十一、个人视角-两种制度-练的是两种能力" tabindex="-1">十一、个人视角：两种制度，练的是两种能力 <a class="header-anchor" href="#十一、个人视角-两种制度-练的是两种能力" aria-label="Permalink to &quot;十一、个人视角：两种制度，练的是两种能力&quot;">​</a></h2><p><strong>项目制练的是&quot;交付确定性&quot;：</strong></p><ul><li>把一件大事拆开、排期、按节点交付</li><li>跨方协调：客户、供应商、内部团队</li><li>在约束（时间、预算、范围）下拿到结果</li></ul><p><strong>产品制练的是&quot;判断力&quot;：</strong></p><ul><li>判断什么值得做、什么必须砍</li><li>用数据验证一个想法，而不是用感觉</li><li>长期主义：接受一件事要做很久才有结果</li></ul><p>两种能力都值钱，但<strong>错配会很痛苦</strong>：</p><ul><li>项目制做久了跳产品制，最不适应的是&quot;没有验收清单了&quot;。没有人告诉你要做什么、做到什么程度算好，一切要自己判断</li><li>产品制做久了跳项目制，最不适应的是&quot;范围不能改&quot;。明明发现需求不对，但合同说不能改，只能照做</li></ul><p>这不是能力问题，是<strong>制度的惯性</strong>。所以换机会的时候，除了看薪资和职级，值得多问一句：<strong>这里是项目制还是产品制？</strong></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ol><li><strong>制度不是组织架构图上的一个框，它会一路下沉到流程的每一步。</strong> 同一个&quot;测试&quot;动作，在项目制里是验收，在产品制里是质量信息；同一个&quot;上线&quot;，一个是句号，一个是逗号。</li><li><strong>根因是收钱的时间点。</strong> 项目制为&quot;做完&quot;收费，产品制为&quot;有用&quot;收费。做完可以签字确认，有用只能用指标证明——这就是两边所有差异的来源。</li><li><strong>同一动作在两边的含义常常相反。</strong> 改需求、重构、写文档、做自动化，在这里还是在那里，含义是反的。</li><li><strong>没有普适的更优解。</strong> 需求确定、一次性交付，项目制的边界感就是优势；需求易变、要持续迭代，产品制的反馈速度就是优势。选错的代价，是&quot;交付完没人管&quot;或者&quot;在明确范围里无休止投入&quot;。</li><li><strong>个人层面：制度决定你能攒下什么。</strong> 项目制攒&quot;交付确定性&quot;，产品制攒&quot;判断力&quot;，两者的错配是具体而真实的痛。</li></ol>',107)])])}const h=o(a,[["render",l]]);export{q as __pageData,h as default};
